mapper.update:
/*updateMasterCmClTaxamntAlterApPopList_KEPTARDT*/

		UPDATE 
		    KEPTAPDT A/* 외상매입_세금계산서 */
		SET 
		    A.SUPP_PRICE      = #{SUPP_PRICE}
		  , A.TAX_PRICE       = #{TAX_PRICE}
		  , A.AMT             = #{SUPP_PRICE}+#{TAX_PRICE}
		  , A.TAX_TYPE        = #{st_tax_type_code}
		  , A.CHANGE_USER_ID  = #{st_user_id}
		  , A.CHANGE_DATE     = TO_CHAR(SYSDATE, 'YYYYMMDD')
		  , A.CHANGE_TIME     = TO_CHAR(SYSDATE, 'HH24MISS')
		WHERE 1=1
		AND A.SITE			  = #{st_site_type}
		AND A.TAX_BILL_NO	  = #{st_tax_bill_no}
		AND A.DEPT_CODE		  = #{DEPT_CODE}

mapper.select:
/*selectMasterCmClTaxamntAlterApPopChkList*/

		SELECT 	SUM(A.TAX_PRICE) AS TOT_TAX_PRICE
			,	SUM(A.SUPP_PRICE) AS TOT_SUPP_PRICE
			,	SUM(A.AMT) AS TOT_AMT
		FROM 	KEPTAPDT A
		WHERE	1=1
		AND 	A.SITE			= #{st_site_type}
		AND 	A.TAX_BILL_NO	= #{st_tax_bill_no}
		GROUP BY A.TAX_BILL_NO

mapper.update:
	/*updateMasterCmClTaxamntAlterApPopList_KEPTARDT2*/

			UPDATE KEPTAPDT A
			SET    A.TOT_TAX_PRICE 	= #{tot_tax_price}
     			 , A.TOT_SUPP_PRICE = #{tot_supp_price}
      			 , A.TOT_AMT 		= #{tot_amt}
		 		 , A.CHANGE_USER_ID	= #{st_user_id}
		 		 , A.CHANGE_DATE	= TO_CHAR(SYSDATE, 'YYYYMMDD')
		 		 , A.CHANGE_TIME	= TO_CHAR(SYSDATE, 'HH24MISS')
			WHERE 1=1
			AND A.SITE            = #{st_site_type}
			AND A.TAX_BILL_NO     = #{st_tax_bill_no}

/*updateMasterCmClTaxamntAlterApPopList_KEPTITEM*/

		UPDATE 
		    KEPTITEM /* 세금계산서 품목정보 */
		SET 
		    REMARK_PRICE = #{tot_supp_price}
		  , SUPP_PRICE   = #{tot_supp_price}
		  , TAX_PRICE    = #{tot_tax_price}
		WHERE 1=1
		AND TAX_BILL_NO  = #{st_tax_bill_no}
